def word_frequency(text: str) -> dict[str, int]:
    punctuation = "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~"
    counts: dict[str, int] = {}
    for token in text.split():
        word = token.strip(punctuation).lower()
        if not word:
            continue
        counts[word] = counts.get(word, 0) + 1
    return counts
